// Node: Code: LLM Router
// Fallback order: Gemini models primary with retries, OpenRouter fallback.

const PROVIDER_ORDER = [
  'gemini:gemini-2.5-flash-lite',
  'gemini:gemini-3.1-flash-lite',
  'gemini:gemini-2.5-flash',
  'gemini:gemini-3.5-flash',
  'openrouter:openrouter/free'
];

const maxRetries = 2;
const timeoutMs = 30000;

const geminiApiKey = $env.GEMINI_API_KEY;
const openrouterApiKey = $env.OPENROUTER_API_KEY;

const item = $input.first().json;
const prompt = item.prompt || item.systemPrompt || '';

async function callGemini(model, attempt = 1) {
  const url = `https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent?key=${geminiApiKey}`;
  try {
    return await this.helpers.httpRequest({
      method: 'POST',
      url,
      timeout: timeoutMs,
      headers: { 'Content-Type': 'application/json' },
      body: { contents: [{ parts: [{ text: prompt }] }] },
      json: true
    });
  } catch (err) {
    if (attempt <= maxRetries && (err.statusCode === 429 || err.statusCode >= 500)) {
      return await callGemini.call(this, model, attempt + 1);
    }
    throw err;
  }
}

async function callOpenRouter(model) {
  const url = 'https://openrouter.ai/api/v1/chat/completions';
  return await this.helpers.httpRequest({
    method: 'POST',
    url,
    timeout: timeoutMs,
    headers: {
      'Authorization': `Bearer ${openrouterApiKey}`,
      'Content-Type': 'application/json'
    },
    body: {
      model,
      messages: [{ role: 'user', content: prompt }]
    },
    json: true
  });
}

for (const target of PROVIDER_ORDER) {
  const [provider, model] = target.split(':');
  try {
    if (provider === 'gemini') {
      const res = await callGemini.call(this, model);
      return [{ json: { provider: target, message: { content: res.candidates[0].content.parts[0].text } } }];
    } else if (provider === 'openrouter') {
      const res = await callOpenRouter.call(this, model);
      return [{ json: { provider: target, message: { content: res.choices[0].message.content } } }];
    }
  } catch (e) {
    // fallback to next provider in PROVIDER_ORDER
  }
}

return [{ json: { error: 'All providers failed in PROVIDER_ORDER fallback chain' } }];
